import { useEffect, useState } from 'react';

type Todo = { id: string; done: boolean };

export function TodoList({ todos, onCount }: { todos: Todo[]; onCount: (n: number) => void }) {
  const [shown, setShown] = useState(0);
  const open = todos.filter((todo) => !todo.done);
  useEffect(() => {
    onCount(open.length);
  }, [open, onCount]);
  return <p onClick={() => setShown(shown + 1)}>{open.length}</p>;
}

import React from 'react';

export const Legend = ({ series }) => {
  const names = Object.keys(series);
  const label = React.useMemo(() => names.join(', '), [names]);
  return <span>{label}</span>;
};

import { useCallback as useStableCallback } from 'react';

export default function Picker({ options, onPick }: { options: { value: string }[]; onPick: (v: string[]) => void }) {
  const values = options.map((option) => option.value) as string[];
  const pickAll = useStableCallback(() => onPick(values), [values, onPick]);
  return <button type="button" onClick={pickAll}>All</button>;
}

import { useLayoutEffect } from 'react';

export function useSelectionSync(selected: Set<string>, sync: (ids: string[]) => void) {
  const ids = Array.from(selected);
  useLayoutEffect(() => {
    sync(ids);
  }, [ids, sync]);
}

import * as React from 'react';

export function Grid({ rows }: { rows?: { cells: number[] }[] }) {
  const cells = rows?.flatMap((row) => row.cells);
  const total = React.useMemo(() => (cells ?? []).reduce((a, b) => a + b, 0), [cells]);
  return <div>{total}</div>;
}

import { useEffect } from 'react';

type Props = { userId: string; load: (id: string) => void };

export function Profile(props: Props) {
  useEffect(() => {
    props.load(props.userId);
  }, [props]);
  return null;
}

import { useMemo } from 'react';

const Price = (props) => {
  const text = useMemo(() => `${props.amount} ${props.currency}`, [props]);
  return <b>{text}</b>;
};

export default Price;

import React, { forwardRef, useCallback } from 'react';

export const Field = forwardRef<HTMLInputElement, { name: string; onEdit: (n: string, v: string) => void }>(function (props, ref) {
  const change = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    props.onEdit(props.name, event.target.value);
  }, [props]);
  return <input ref={ref} onChange={change} />;
});

import { useMemo } from 'react';
import { panelOptions } from './panel-options';

type Props = { width: number; title: string };

export function SidePanel(props: Props) {
  const options = useMemo(() => panelOptions(props), [props]);
  return <aside style={{ width: options.width }}>{options.title}</aside>;
}

import React, { useCallback } from 'react';
import { Preview } from './Preview';

export function Asset(props) {
  const renderPreview = useCallback(() => <Preview {...props} compact />, [props]);
  return <div>{renderPreview()}</div>;
}

import { useCallback } from 'react';

export function Dashboard(props: { panelId: string; emit: (id: string) => void }) {
  const { panelId, emit } = props;
  const onAdd = useCallback(() => emit(panelId), [panelId, emit, props]);
  return <button type="button" onClick={onAdd}>Add</button>;
}

import * as R from 'react';

export function Tags({ tags }: { tags: { name: string; hidden: boolean }[] }) {
  const visible = tags.filter((tag) => !tag.hidden);
  const label = R.useMemo(() => visible.map((t) => t.name).join(', '), [visible]);
  return <span>{label}</span>;
}

import React from 'react';

const { useEffect } = React;

export function Status(props) {
  useEffect(() => {
    props.onStatus(props.code);
  }, [props]);
  return null;
}

import * as R from 'react';

export const Toggle = R.forwardRef<HTMLButtonElement, { on: boolean; report: (on: boolean) => void }>((props, ref) => {
  R.useEffect(() => {
    props.report(props.on);
  }, [props]);
  return <button type="button" ref={ref} />;
});

import { useEffect } from 'react';

export function Crumbs({ path, onDepth }: { path: string; onDepth: (n: number) => void }) {
  const segments = path.split('/');
  useEffect(() => {
    onDepth(segments.length);
  }, [segments, onDepth]);
  return null;
}

import { useMemo } from 'react';

export function useQueryString(pairs: [string, string][]) {
  const query = Object.fromEntries(pairs);
  return useMemo(() => new URLSearchParams(query).toString(), [query]);
}

import { useEffect } from 'react';

export function Theme({ base, overrides, apply }) {
  const theme = Object.assign({}, base, overrides);
  useEffect(() => {
    apply(theme);
  }, [theme, apply]);
  return null;
}

import { useMemo as useM } from 'react';
import { parse } from './parse';

export function Parsed(props: { text: string; strict: boolean }) {
  const tree = useM(() => parse(props), [props]);
  return <pre>{tree.length}</pre>;
}

