import { useEffect } from 'react';

type Props = { userId: string; load: (id: string) => void };

export function Profile({ userId, load }: Props) {
  useEffect(() => {
    load(userId);
  }, [userId, load]);
  return null;
}

import { forwardRef, useImperativeHandle, useEffect } from 'react';

export const TextBox = forwardRef<{ focus: () => void }, { label: string }>((props, ref) => {
  useEffect(() => {
    if (typeof ref === 'function') ref(null);
  }, [ref]);
  return <label>{props.label}</label>;
});

import { useEffect } from 'react';

export function Search({ query, run }: { query: string; run: (q: string) => void }) {
  const prefix = query.slice(0, 3);
  const tags = query.split(' ').map((t) => t.trim()).join(',');
  useEffect(() => {
    run(prefix + tags);
  }, [prefix, tags, run]);
  return null;
}

import { useEffect, useRef } from 'react';

type Props = { onSubmit: () => void; onReset: () => void };

export function Form(props: Props) {
  const latest = useRef(props);
  useEffect(() => {
    latest.current = props;
  }, [props]);
  return <form onSubmit={() => latest.current.onSubmit()} />;
}

import { useEffect } from 'react';

export function Counter({ items, report }: { items: number[]; report: (n: number) => void }) {
  const positive = items.filter((n) => n > 0);
  useEffect(() => {
    report(positive.length);
  }, [positive.length, report]);
  return null;
}

import { useMemo } from 'react';

const PALETTE = { red: '#f00', blue: '#00f' };
const COLOR_NAMES = Object.keys(PALETTE);

export function Chart({ index }: { index: number }) {
  const color = useMemo(() => COLOR_NAMES[index % COLOR_NAMES.length], [index, COLOR_NAMES]);
  return <i style={{ color }} />;
}

import { useEffect } from 'react';

export function usePoll(options: { url: string; every: number }) {
  useEffect(() => {
    const id = setInterval(() => fetch(options.url), options.every);
    return () => clearInterval(id);
  }, [options]);
}

import { useMemo } from './memo';

export function Tabs({ tabs }: { tabs: { id: string }[] }) {
  const ids = tabs.map((tab) => tab.id);
  const key = useMemo(() => ids.join('-'), [ids]);
  return <nav data-key={key} />;
}

import { useCallback } from 'react';

export function Toolbar({ actions }: { actions: { id: string; run: () => void }[] }) {
  const runAll = useCallback(() => {
    const enabled = actions.filter((a) => a.id !== 'off');
    enabled.forEach((a) => a.run());
  }, [actions]);
  return <button type="button" onClick={runAll}>Run</button>;
}

import { useEffect, useRef } from 'react';
import { createCalendarStore } from './store';

export function Calendar(props: { days: number; start: Date }) {
  const store = useRef(createCalendarStore());
  useEffect(() => {
    store.current.getState().sync(props);
  }, [props]);
  return null;
}

import { useEffect } from 'react';
import type { View } from './view';

export function TrackLoad(view: View, { loading }: { loading: boolean }) {
  useEffect(() => {
    if (!loading) view.report();
  }, [view, loading]);
}

import { useMemo } from 'react';

export function Heading(text: string) {
  const words = useMemo(() => text.split(' ').length, [text]);
  return <h2 data-words={words}>{text}</h2>;
}

import { useMemo } from 'react';

export function TagsStory({ tags }: { tags: string[] }) {
  const upper = tags.map((t) => t.toUpperCase());
  const label = useMemo(() => upper.join(', '), [upper]);
  return <span>{label}</span>;
}

import { useEffect } from 'react';
import { observer } from 'mobx-react';

export const Row = observer(props => {
  useEffect(() => {
    props.onShow(props.id);
  }, [props]);
  return null;
});

import { memo, useMemo } from 'react';
import { buildRows } from './rows';

export const Table = memo(function Table(props: { data: number[]; sort: string }) {
  const rows = useMemo(() => buildRows(props), [props]);
  return <table>{rows}</table>;
});

import React from 'react';

export const Marker = React.memo((props) => {
  React.useEffect(() => {
    props.map.move(props.id, props.at);
  }, [props]);
  return null;
});

import { useCallback } from 'react';
import { observer } from 'mobx-react';

function Editor(props: { onSave: (o: { autosave: boolean }) => void }) {
  const onBlur = useCallback(() => props.onSave({ autosave: true }), [props]);
  return <textarea onBlur={onBlur} />;
}

export default observer(Editor);

import * as R from 'react';
import { resolvePath } from './path';

const FormInput = (props: { path: string[]; relative: string[] }) => {
  const absolute = R.useMemo(() => resolvePath(props), [props]);
  return <span>{absolute.join('.')}</span>;
};

export default R.memo(FormInput);

import { forwardRef, memo, useCallback } from 'react';

export const SearchBox = memo(forwardRef((props, ref) => {
  const submit = useCallback(() => props.onSearch(props.query), [props]);
  return <input ref={ref} onBlur={submit} />;
}));

import { useEffect } from 'react';

export function Merge({ state, patch, commit }: { state: object; patch: object; commit: (s: object) => void }) {
  const merged = Object.assign(state, patch);
  useEffect(() => {
    commit(merged);
  }, [merged, commit]);
  return null;
}

import { useMemo } from 'react';

export function TagCount({ tags }: { tags: Set<string> }) {
  const count = useMemo(() => tags.size * 2, [Array.from(tags)]);
  return <span>{count}</span>;
}

import { useCallback } from 'react';
import { connect } from 'react-redux';
import Dialog from './Dialog';

interface Props {
  folderId: string;
  onClose: () => void;
}

export function PublishFolderDialog(props: Props) {
  const onClose = useCallback(() => {
    props.onClose();
  }, [props]);
  return <Dialog folderId={props.folderId} onClose={onClose} />;
}

const mapStateToProps = (state: { folders: string[] }) => ({ folders: state.folders });

export default connect(mapStateToProps)(PublishFolderDialog);
